      msteps ASEGS (mkst regs (0x6c4ec : word) M rom) (mkst regs' (0x6c540 : word) M rom)
      /\ cRqa_post (bytes_le_to_Z w0) (bytes_le_to_Z w1) regs' /\ keeps_but RIPL regs regs'.
Proof.
