      msteps ASEGS (mkst regs (0x13f738 : word) M rom) (mkst regs' (if Z.eqb k rem then (0x13f6b8 : word) else (0x13f744 : word)) M rom)
      /\ getr regs' 10 = Z_to_bv 64 k /\ getr regs' 19 = Z_to_bv 64 q /\ keeps_but [1; 19]%bv regs regs'.
Proof.
