(* [comment removed for export] *)
Definition zsh (M : word -> option byte) (p n : Z) : Prop :=
  forall x : word, (SB + p / 8) - (SB + p / 8) mod 8 <= bv_unsigned x < (SB + (p + n - 1) / 8) - (SB + (p + n - 1) / 8) mod 8 + 8 -> M x = Some (Z_to_bv 8 0).
